"""Generates sim/tb/axis/tb_usb2_axis.sv from sim/tb/tb_usb2_utmi_axim.sv (R-276): the DUT is the AXI4-slave wrapper m_usb2_top_utmi_axis.
The master-side memory model of the generic harness is replaced by an AXI4 master BFM that the scenario drives with the operations
  AW burst addr beats expresp d0 d1 ...   write burst (burst 0 FIXED, 1 INCR), response checked against expresp (0 OKAY, 2 SLVERR)
  AR burst addr beats expresp d0 m0 d1 m1 ...   read burst, each beat compared under its mask (only when expresp = 0)
  AWN/AWS/AWJ                             background write burst, check that it is still stalled, join it
  DR ch value tmo                         wait until o_dma_req[ch] equals value (bus cycles)
  DX ch value                             check o_dma_req[ch] now
  DA ch                                   one-cycle pulse on i_dma_ack[ch]
Protocol monitors a_axis_* check the slave outputs (stability until ready, no response without a request, RLAST position, IDs).
Deterministic; run from the sim folder:  python scripts/gen_axis_tb.py  (add --check to compare only)."""
import os
import sys

import sys as _sys
_sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import vpaths as P  # noqa: E402
SIM = P.V
SRC = os.path.join(P.TB, 'tb_usb2_utmi_axim.sv')
DST = os.path.join(P.TB, 'tb_usb2_axis.sv')

s = open(SRC).read()
s = s.replace('module tb_usb2_utmi_axim;', 'module tb_usb2_axis;')
s = s.replace('// Generic harness for the wrapper m_usb2_top_utmi_axim',
              '// GENERATED by scripts/gen_axis_tb.py from tb_usb2_utmi_axim.sv. Generic harness for the wrapper m_usb2_top_utmi_axis with an AXI4 master BFM')
# AXI signals are now driven by the master BFM (no initial values on the DUT outputs)
s = s.replace('logic [3:0] bid = 0; logic [1:0] bresp = 0; logic bvalid = 0, bready;', 'logic [3:0] bid; logic [1:0] bresp; logic bvalid, bready = 1;')
s = s.replace('logic [3:0] arprot; logic arvalid, arready; logic [3:0] rid = 0; logic [AXI_DATA_W-1:0] rdata = 0; logic [1:0] rresp = 0;',
              'logic [3:0] arprot; logic arvalid = 0, arready; logic [3:0] rid; logic [AXI_DATA_W-1:0] rdata; logic [1:0] rresp;')
s = s.replace('logic rlast = 0, rvalid = 0, rready; logic int_usb', 'logic rlast, rvalid, rready = 1; logic int_usb')
s = s.replace('logic awvalid, awready;', 'logic awvalid = 0, awready;')
s = s.replace('logic wlast, wvalid, wready;', 'logic wlast = 0, wvalid = 0, wready;')
s = s.replace('logic [3:0] awid; logic [31:0] awaddr;', 'logic [3:0] awid = 0; logic [31:0] awaddr = 0;')
s = s.replace('  parameter int SG_EN = 0,', '  parameter int NUM_DMA_CH = 4;                     // AXI-slave builds: number of window channels\n  parameter int SG_EN = 0,', 1)
# DUT instance
a = s.index('  m_usb2_top_utmi_axim #(')
b = s.index('.o_axim_rready(rready));', a) + len('.o_axim_rready(rready));')
inst = s[a:b]
lines = inst.split('\n')
first = [i for i, x in enumerate(lines) if x.rstrip().endswith('dut (')][0] + 1
keep = [ln for ln in lines[first:] if ln.startswith('    .') and 'axim' not in ln]
new = '''  logic [NUM_DMA_CH-1:0] dma_req, dma_ack = 0;
  m_usb2_top_utmi_axis #(.PARA_USB2_ROLE(ROLE), .PARA_USB2_NUM_EP(NUM_EP), .PARA_USB2_NUM_HC(NUM_HC), .PARA_USB2_UTMI_W(UTMI_W),
    .PARA_USB2_AXI_DATA_W(AXI_DATA_W), .PARA_USB2_FIFO_DEPTH(FIFO_DEPTH), .PARA_USB2_SG_EN(SG_EN), .PARA_USB2_LPM_EN(LPM_EN),
    .PARA_USB2_SPLIT_EN(SPLIT_EN), .PARA_USB2_TSCALE(TSCALE), .PARA_USB2_PIPE_PHY_IN(PIPE), .PARA_USB2_PIPE_RX(PIPE),
    .PARA_USB2_PIPE_CRC(PIPE), .PARA_USB2_PIPE_MODE(PIPE), .PARA_USB2_PIPE_XREG(PIPE), .PARA_USB2_RAM_1P(PIPE), .PARA_USB2_PIPE_AXS(PIPE),
    .PARA_USB2_NUM_DMA_CH(NUM_DMA_CH)) dut (
''' + '\n'.join(keep) + '''
    .i_axis_awid(awid), .i_axis_awaddr(awaddr), .i_axis_awlen(awlen), .i_axis_awsize(awsize), .i_axis_awburst(awburst),
    .i_axis_awvalid(awvalid), .o_axis_awready(awready), .i_axis_wdata(wdata), .i_axis_wstrb(wstrb), .i_axis_wlast(wlast),
    .i_axis_wvalid(wvalid), .o_axis_wready(wready), .o_axis_bid(bid), .o_axis_bresp(bresp), .o_axis_bvalid(bvalid),
    .i_axis_bready(bready), .i_axis_arid(arid), .i_axis_araddr(araddr), .i_axis_arlen(arlen), .i_axis_arsize(arsize),
    .i_axis_arburst(arburst), .i_axis_arvalid(arvalid), .o_axis_arready(arready), .o_axis_rid(rid), .o_axis_rdata(rdata),
    .o_axis_rresp(rresp), .o_axis_rlast(rlast), .o_axis_rvalid(rvalid), .i_axis_rready(rready),
    .o_dma_req(dma_req), .i_dma_ack(dma_ack));'''
s = s[:a] + new + s[b:]
# master BFM in place of the memory model
m0 = s.index('  // ------------------------------------------------------------------ axi_mem_model')
m1 = s.index('  // ------------------------------------------------------------------ apb_bfm')
BFM = r'''  // ------------------------------------------------------------------ axi_master_bfm (AXI4 master of the slave wrapper) and monitors
  byte unsigned mem [0:1048575];                       // scoreboard memory of the scenario (MW and MC operations)
  int bp_pct = 0; int unsigned lfsr = 32'h1ACEB00C;     // throttling of WVALID, BREADY and RREADY in percent
  int err_wr_at = -1, err_rd_at = -1, err_code = 2;
  bit win_on = 0; int win_lo = 0, win_hi = 0, act_win = 0;
  function automatic bit bp_now();
    lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
    return (int'(lfsr % 100) < bp_pct);
  endfunction
  int unsigned ax_data [$];                            // beat data of the operation being read from the ops file
  int act_axs = 0, ax_wr_beats = 0, ax_wr_bursts = 0, ax_rd_beats = 0, ax_rd_bursts = 0, ax_err_resp = 0;
  int ax_bg_busy = 0, ax_bg_done = 0;
  task automatic ax_write(input int burst, input int a, input int n, input int exp, input int unsigned dq [$], input int tmo = 4000);
    int w; bit seen;
    @(posedge clk_bus); awid <= 4'(ax_wr_bursts); awaddr <= 32'(a); awlen <= 8'(n - 1); awsize <= 3'($clog2(DB)); awburst <= 2'(burst); awvalid <= 1;
    w = 0; do begin @(posedge clk_bus); w++; if (w > 4000) begin a_fail("a_axis", "no AWREADY within 4000 cycles"); break; end end while (!awready);
    awvalid <= 0;
    for (int i = 0; i < n; i++) begin
      while (bp_now()) begin wvalid <= 0; @(posedge clk_bus); end
      wvalid <= 1; wdata <= AXI_DATA_W'(dq[i]); wstrb <= '1; wlast <= (i == n - 1);
      w = 0; do begin @(posedge clk_bus); w++; if (w > tmo) begin a_fail("a_axis", $sformatf("no WREADY within %0d cycles", tmo)); break; end end while (!wready);
      ax_wr_beats++;
    end
    wvalid <= 0; wlast <= 0;
    seen = 0; w = 0;
    while (!seen) begin
      bready <= !bp_now(); @(posedge clk_bus); w++;
      if (bvalid && bready) seen = 1;
      if (w > 4000) begin a_fail("a_axis", "no BVALID within 4000 cycles"); break; end
    end
    if (seen) begin
      chk(int'(bresp) == exp, $sformatf("line %0d: write burst at %08x: BRESP %0d expected %0d", line_no, a, bresp, exp));
      chk(bid == awid, $sformatf("line %0d: BID %0d does not match AWID %0d", line_no, bid, awid));
      if (bresp != 0) ax_err_resp++;
    end
    bready <= 1; ax_wr_bursts++; act_axim++; act_axs++;
  endtask
  task automatic ax_read(input int burst, input int a, input int n, input int exp);
    int w, got, bad, first; bit last_seen;
    @(posedge clk_bus); arid <= 4'(ax_rd_bursts); araddr <= 32'(a); arlen <= 8'(n - 1); arsize <= 3'($clog2(DB)); arburst <= 2'(burst); arvalid <= 1;
    w = 0; do begin @(posedge clk_bus); w++; if (w > 4000) begin a_fail("a_axis", "no ARREADY within 4000 cycles"); break; end end while (!arready);
    arvalid <= 0;
    got = 0; bad = 0; first = -1; last_seen = 0; w = 0;
    while (!last_seen) begin
      rready <= !bp_now(); @(posedge clk_bus); w++;
      if (rvalid && rready) begin
        chk(int'(rresp) == exp, $sformatf("line %0d: read beat %0d: RRESP %0d expected %0d", line_no, got, rresp, exp));
        chk(rid == arid, $sformatf("line %0d: RID %0d does not match ARID %0d", line_no, rid, arid));
        chk(rlast == (got == n - 1), $sformatf("line %0d: RLAST %0b at beat %0d of %0d", line_no, rlast, got, n));
        if (exp == 0 && 2 * got + 1 < ax_data.size() && ((rdata ^ AXI_DATA_W'(ax_data[2 * got])) & AXI_DATA_W'(ax_data[2 * got + 1])) != 0) begin bad++; if (first < 0) first = got; end
        if (rresp != 0) ax_err_resp++;
        got++; ax_rd_beats++; w = 0;
        if (rlast || got >= n) last_seen = 1;
      end
      if (w > 4000) begin a_fail("a_axis", $sformatf("no RVALID within 4000 cycles (beat %0d of %0d)", got, n)); break; end
    end
    chk(got == n, $sformatf("line %0d: %0d read beat(s), expected %0d", line_no, got, n));
    chk(bad == 0, $sformatf("line %0d: %0d read beat(s) differ from the expected data, first beat %0d", line_no, bad, first));
    rready <= 1; ax_rd_bursts++; act_axim++; act_axs++;
  endtask
  // a_dmareq (REQ-IF-009, DEC-036): a request that falls while no burst is in progress must have been answered by an acknowledge
  logic [3:0] dreq_d = 0, dack_d = 0; int act_dmareq_chk = 0;
  always @(posedge clk_bus) begin
    if (rst_n) begin
      for (int c = 0; c < NUM_DMA_CH; c++) begin
        if (dreq_d[c]) act_dmareq_chk++;
        if (dreq_d[c] && !dma_req[c] && !dack_d[c] && aw_open == 0 && ar_open == 0 && !awvalid && !arvalid && !wvalid)
          a_fail("a_dmareq", $sformatf("o_dma_req[%0d] fell without an acknowledge and without a burst", c));
      end
    end
    dreq_d <= dma_req; dack_d <= dma_ack;
  end
  // a_axis: responses are stable until accepted, and nothing is answered without a request
  logic bv_d = 0, br_d = 0, rv_d = 0, rr_d = 0; logic [3:0] bid_d, rid_d; logic [1:0] bresp_d, rresp_d; logic rlast_d; logic [AXI_DATA_W-1:0] rdata_d;
  int aw_open = 0, ar_open = 0, w_last_cnt = 0, act_axis_chk = 0;
  always @(posedge clk_bus) begin
    if (rst_n) begin
      if (bv_d && !br_d && (!bvalid || bid != bid_d || bresp != bresp_d)) a_fail("a_axis", "BVALID or its payload changed before BREADY");
      if (rv_d && !rr_d && (!rvalid || rid != rid_d || rresp != rresp_d || rlast != rlast_d || rdata != rdata_d)) a_fail("a_axis", "RVALID or its payload changed before RREADY");
      if (awvalid && awready) aw_open++;
      if (wvalid && wready && wlast) w_last_cnt++;
      if (bvalid && bready) begin
        act_axis_chk++;
        if (aw_open == 0) a_fail("a_axis", "BVALID without an accepted write address");
        else if (w_last_cnt == 0) a_fail("a_axis", "BVALID before the last write beat");
        else begin aw_open--; w_last_cnt--; end
      end
      if (arvalid && arready) ar_open++;
      if (rvalid && rready && rlast) begin
        act_axis_chk++;
        if (ar_open == 0) a_fail("a_axis", "RVALID without an accepted read address"); else ar_open--;
      end
      if (wready && aw_open == 0 && !(awvalid && awready)) a_fail("a_axis", "WREADY without an accepted write address");
    end
    bv_d <= bvalid; br_d <= bready; bid_d <= bid; bresp_d <= bresp;
    rv_d <= rvalid; rr_d <= rready; rid_d <= rid; rresp_d <= rresp; rlast_d <= rlast; rdata_d <= rdata;
  end

'''
s = s[:m0] + BFM + s[m1:]
# read-only probe of the slave read path, enabled with +axsdbg=<t0 ps> +axsdbg_t1=<t1 ps>
PROBE = r"""  longint axs_t0, axs_t1; initial begin if (!$value$plusargs("axsdbg=%d", axs_t0)) axs_t0 = -1; if (!$value$plusargs("axsdbg_t1=%d", axs_t1)) axs_t1 = 0; end
  always @(posedge clk_bus) if (axs_t0 >= 0 && $time >= axs_t0 && $time <= axs_t1) $display("AXSDBG %0t st=%0d rl=%0d rq=%0d beats=%0d rsvld=%b rqvld=%b rqrdy=%b rvalid=%b rready=%b rdata=%h cnt=%0d", $time,
    dut.u_core.gen_axs.u_axs.reg_fsm_rd_current_state, dut.u_core.gen_axs.u_axs.reg_r_left, dut.u_core.gen_axs.u_axs.reg_r_rq_left, dut.u_core.gen_axs.u_axs.reg_r_beats,
    dut.u_core.gen_axs.u_axs.i_rs_vld, dut.u_core.gen_axs.u_axs.o_rq_vld, dut.u_core.gen_axs.u_axs.i_rq_rdy, rvalid, rready, rdata, dut.u_core.gen_axs.u_axs.reg_evq_cnt);
"""
# operations
OPS = '''        "AW": begin int bu, ad, nb, ex; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); ax_data.delete(); for (int i = 0; i < nb; i++) ax_data.push_back(rdi()); ax_write(bu, ad, nb, ex, ax_data); end
        "AWN": begin   // write burst launched in the background (it may stall on a full region); joined by AWJ
          int bu, ad, nb, ex; int unsigned dq [$]; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); for (int i = 0; i < nb; i++) dq.push_back(rdi());
          ax_bg_busy++; ax_bg_done = 0;
          fork begin int unsigned c [$]; c = dq; ax_write(bu, ad, nb, ex, c, 200000); ax_bg_busy--; ax_bg_done = 1; end join_none
        end
        "AWS": begin int w; w = rdi(); repeat (w) @(posedge clk_bus); chk(ax_bg_busy != 0, $sformatf("line %0d: the background write finished although the region is full", line_no)); end
        "AWJ": begin int w; w = rdi(); for (int i = 0; i < w && ax_bg_busy != 0; i++) @(posedge clk_bus); chk(ax_bg_busy == 0, $sformatf("line %0d: the background write did not finish within %0d bus cycles", line_no, w)); end
        "AR": begin int bu, ad, nb, ex; bu = rdi(); ad = rdi(); nb = rdi(); ex = rdi(); ax_data.delete(); if (ex == 0) for (int i = 0; i < 2 * nb; i++) ax_data.push_back(rdi()); ax_read(bu, ad, nb, ex); end
        "DR": begin int ch, v, tm; bit ok; ch = rdi(); v = rdi(); tm = rdi(); ok = 0; for (int i = 0; i < tm && !ok; i++) begin @(posedge clk_bus); ok = (dma_req[ch] == v[0]); end
                chk(ok, $sformatf("line %0d: o_dma_req[%0d] did not reach %0d within %0d bus cycles", line_no, ch, v, tm)); act_dmareq++; end
        "DX": begin int ch, v; ch = rdi(); v = rdi(); @(posedge clk_bus); chk(dma_req[ch] == v[0], $sformatf("line %0d: o_dma_req[%0d] is %0b, expected %0d", line_no, ch, dma_req[ch], v)); act_dmareq++; end
        "DA": begin int ch; ch = rdi(); @(posedge clk_bus); dma_ack[ch] <= 1; @(posedge clk_bus); dma_ack[ch] <= 0; act_dmareq++; end
'''
s = s.replace('  // ------------------------------------------------------------------ apb_bfm', PROBE + '  // ------------------------------------------------------------------ apb_bfm', 1)
s = s.replace('        "WD": begin', OPS + '        "WD": begin', 1)
s = s.replace('int act_utmi_tx = 0,', 'int act_dmareq = 0; int act_utmi_tx = 0,', 1)
s = s.replace('"#activity a_utmi_tx=%0d a_axim=%0d a_apb=%0d sof=%0d", act_utmi_tx, act_axim, act_apb, sof_cnt);',
              '"#activity a_utmi_tx=%0d a_axis=%0d a_apb=%0d sof=%0d dmareq=%0d a_dmareq_checks=%0d", act_utmi_tx, act_axim, act_apb, sof_cnt, act_dmareq, act_dmareq_chk);')
out = s
if '--check' in sys.argv:
    same = os.path.exists(DST) and open(DST).read() == out
    print('SAME' if same else 'DIFF')
    sys.exit(0 if same else 1)
os.makedirs(os.path.dirname(DST), exist_ok=True)
open(DST, 'w', newline='\n').write(out)
print('wrote', DST)
